document.querySelector('#start').onclick=()=>beginIntro();canvas.onclick=()=>{if(active)canvas.requestPointerLock?.()};addEventListener('keydown',e=>{if(e.key.startsWith('Arrow'))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='y'&&!e.repeat)comfortBoy();if(e.key.toLowerCase()==='t'&&!e.repeat)cycleTimerSize();if((e.key.toLowerCase()==='e'||e.key==='Escape')&&evidenceOpen&&!e.repeat){closeEvidence();return}if(e.key.toLowerCase()==='e'&&active&&!e.repeat)interact();if(e.key==='Escape')pause();if(e.key.toLowerCase()==='m'){muted=!muted;if(gain)gain.gain.value=muted?0:.025;if(muted)hush()}});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',pause);document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&active)pause()});addEventListener('mousemove',e=>{if(active&&document.pointerLockElement)p.a+=e.movementX*.0022});document.querySelectorAll('[data-k]').forEach(b=>{b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);keys[b.dataset.k]=true};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.k]=false});document.querySelector('#use').onclick=()=>active&&interact();document.querySelector('#comfort').onclick=comfortBoy;function resize(){canvas.width=Math.min(1100,innerWidth);canvas.height=Math.round(canvas.width*innerHeight/innerWidth)}addEventListener('resize',resize);resize();reset();function frame(t){let elapsed=Math.max(0,(t-last)/1000),dt=Math.min(.04,elapsed);last=t;tickIntro(Math.min(elapsed,.1));if(active){time+=Math.max(0,elapsed-dt);update(dt);}if(ellisMemoryPlaying){tickEllisMemory(dt);drawEllisMemory()}else if(transformationPlaying){tickTransformation(dt);drawTransformation()}else if(danielDeathPlaying){tickDanielDeath(dt);drawDanielDeath()}else if(introPlaying)drawIntro();else draw();if(ellisMemoryPlaying)analogFinish(document.querySelector("#ellisMemoryView"),ellisMemoryClock,1.1);else if(transformationPlaying)analogFinish(document.querySelector("#transformationView"),transformationClock,1.2);else if(danielDeathPlaying)analogFinish(document.querySelector("#deathView"),danielDeathClock,1.6);else if(introPlaying)analogFinish(document.querySelector("#introView"),introClock,.8);else analogFinish(canvas,time,1);requestAnimationFrame(frame)}requestAnimationFrame(frame);

document.querySelector("#resetRun").onclick=()=>{introPlaying=false;document.querySelector("#cinema").hidden=true;document.querySelector("#danielDeath").hidden=true;runStarted=true;reset();document.querySelector("h1").innerHTML="AFTER<br><i>HOURS.</i>";start()};


let introPlaying=false,introClock=0,introScene=-1,runStarted=false;
const introScenes=[
 ['YESTERDAY · 11:46 PM','A message from your own number.','You lift the phone. Your own voice whispers: “You’re late again.” Behind it, a child sings a tune you almost remember.'],
 ['TODAY · 12:03 AM','A badge inside your coat.','You have never worked for Argus. The photograph shows you older. You turn the badge over: THREE RECORDS. THEN THE STAIRS.'],
 ['ARGUS BUILDING · 02:09 AM','The door opens before you knock.','Rain follows you into an empty reception. On the desk, an archive folder lies open. Your hand is already reaching for it.'],
 ['ARCHIVE / 1994','Forty-six desks. Forty-seven names.','A clerk named Daniel Vale brought his son to work. The office entered Ellis into payroll. Daniel crossed the boy’s name out and wrote his own. He was already on the sheet.'],
 ['PERSONNEL CONTINUITY','One father. Two appointments.','The office kept Daniel’s first position at his desk. It stretched the second through the ceiling void, assigning him to find the missing dependent. The wet marks overhead are his.'],
 ['DEPENDENT VISITOR / ELLIS VALE','The song has no final verse.','Daniel told Ellis to sing so they could find each other. The boy is still waiting. When he goes quiet, crouch. If he cries, comfort him before his father comes searching.'],
 ['AN UNSENT LETTER','“Don’t look up to see if it’s me.”','“There are too many corridors inside me. When I try to say your name, the vents open. I don’t want the last face you remember to be this one. — Dad”'],
 ['A NOTE IN YOUR HANDWRITING','You have reached the stairs before.','“Last time, someone called from the landing. You turned around. Take Daniel’s record, Ellis’s visitor file, and your unsigned application. Don’t sit down.”'],
 ['ELEVATOR · 02:16 AM','Eight floors. Nine buttons.','You press the ground floor. The elevator goes up. Through the speaker: “If he cries, tell him I’m still here.” Your reflection lowers its hand a moment after you do.'],
 ['FLOOR 09 · 02:17 AM','Your chair has been kept warm.','The doors open. Every employee turns toward you. Somewhere above the tiles, a father listens to his son. The attendance sheet has one line left to fill.']
];
const introSceneLength=8,introDuration=introScenes.length*introSceneLength;
function showIntroScene(i){introScene=i;document.querySelector('#cinema').dataset.scene=String(i);document.querySelector('#filmCounter').textContent=String(i+1).padStart(2,'0')+' / '+String(introScenes.length).padStart(2,'0');document.querySelector('#filmWhen').textContent=introScenes[i][0];document.querySelector('#filmTitle').textContent=introScenes[i][1];document.querySelector('#filmCaption').textContent=introScenes[i][2]}
function beginIntro(){if(runStarted&&!ended){start();return}reset();introClock=0;introPlaying=true;active=false;overlay.style.display='none';document.querySelector('#cinema').hidden=false;document.querySelector('#enterFilm').hidden=true;document.querySelector('#skipFilm').hidden=false;document.querySelector('#filmProgress').style.width='0%';sound();showIntroScene(0)}
function finishIntro(){introPlaying=false;document.querySelector('#cinema').hidden=true;runStarted=true;keys={};start()}
function tickIntro(dt){if(!introPlaying||document.hidden)return;introClock=Math.min(introDuration,introClock+dt);let i=Math.min(introScenes.length-1,Math.floor(introClock/introSceneLength));if(i!==introScene)showIntroScene(i);document.querySelector('#filmProgress').style.width=(introClock/introDuration*100)+'%';if(introClock>=introDuration){document.querySelector('#enterFilm').hidden=false;document.querySelector('#skipFilm').hidden=true}}
document.querySelector('#skipFilm').onclick=finishIntro;document.querySelector('#enterFilm').onclick=finishIntro;document.querySelector('#start').onclick=beginIntro;

